mapper.select:
SELECT id, apply_id, node_order, node_code, node_name, approver_user_id, approver_name, status, approve_time, approve_comment, create_time, update_time FROM attendance_patch_apply_node WHERE apply_id IN
#{item}
ORDER BY apply_id ASC, node_order ASC, id ASC

mapper.update:
UPDATE attendance_patch_apply_node
SET status = #{status},
    approve_time = #{approveTime},
    approve_comment = #{approveComment},
    update_time = #{updateTime}
WHERE id = #{id}

UPDATE attendance_patch_apply_node
SET status = 'PENDING',
    update_time = #{updateTime}
WHERE id = #{id}
  AND status = 'WAITING'

UPDATE attendance_patch_apply_node
SET status = #{targetStatus},
    update_time = #{updateTime}
WHERE apply_id = #{applyId}
  AND node_order >= #{minNodeOrder}
  AND status = 'WAITING'
